abbrev Label := ℕ × ℕ × ℕ
def labels (d : MediumAtom) (p m : ℕ) : Finset Label :=
  d.cleanedCommonPProgression p m ×ˢ (factorCarrier d.Q2 ×ˢ factorCarrier d.Q3)
def coeff (d : MediumAtom) (p m : ℕ) (l : Label) : ℂ :=
  if Int.ModEq (p * l.2.1 * l.2.2) ((m : ℤ) * l.1) d.residue
  then d.gamma2 l.2.1 * d.gamma3 l.2.2 * d.cleanedAlphaAtom.transposedAtom.beta l.1 else 0
def keep (d : MediumAtom) (H : ℝ) (m : ℕ) (l : Label) : Prop :=
  (fouvryTau 4 (CommonPM2FiniteFold.shiftDifference d (m * l.1)) : ℝ) ≤ H
def pairForm {ι : Type*} (s : Finset ι) (c : ι → ℂ) (G : ι → ι → ℂ) : ℂ :=
  ∑ i ∈ s, ∑ j ∈ s, G i j * c i * star (c j)
def fullPair (d : MediumAtom) (G : ℕ → ℕ → Label → Label → ℂ) (p m : ℕ) : ℂ :=
  pairForm (labels d p m) (coeff d p m) (G p m)
def keptPair (d : MediumAtom) (H : ℝ) (G : ℕ → ℕ → Label → Label → ℂ)
    (p m : ℕ) : ℂ :=
  pairForm (labels d p m) (fun l => if keep d H m l then coeff d p m l else 0) (G p m)

/-- Absolute masses, not norms of cancelling row sums. -/
theorem finite_pair_restore_le {ι : Type*} (s : Finset ι) (c : ι → ℂ)
    (k : ι → Prop) [DecidablePred k] (G : ι → ι → ℂ)

def truncatedCenteredRow (d : MediumAtom) (H : ℝ) (p m : ℕ) : ℂ :=
  keptProgressionRow d H p m -
    (d.cleanedAlphaAtom.q1SliceAtom p).transposedAtom.complexPrincipalRow m

def MediumAtom.commonSmoothCarrier (d : MediumAtom) : Finset ℕ :=
  Finset.Icc 0 (Nat.ceil (3 * d.U))

def MediumAtom.commonSmoothWeight (d : MediumAtom) (n : ℕ) : ℝ :=
  CommonSmoothCutoff.scaledDyadicCutoff d.U (n : ℝ)

theorem MediumAtom.commonSmoothWeight_nonneg (d : MediumAtom) (n : ℕ) :
    0 ≤ d.commonSmoothWeight n := CommonSmoothCutoff.scaledDyadicCutoff_nonneg _ _

def outsideEnergy (d : MediumAtom) : ℝ :=
  (∑ m ∈ d.betaCarrier, ‖d.beta m‖ ^ 2) *
    (∑ p ∈ d.primitiveFirstFactorCarrier, ‖d.gamma1 p‖ ^ 2)
